using System.ComponentModel.DataAnnotations; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Tanda.Domain.Abstractions; using Tanda.Domain.Entities;
namespace Tanda.Web.Pages.Catalog.Additions;
[Authorize(Roles="Administrator")] public class EditModel(IAdditionRepository additions,IProductRepository products):PageModel{[BindProperty]public InputModel Input{get;set;}=new();public Product? Product{get;private set;}public class InputModel{public Guid Id{get;set;}public Guid ProductId{get;set;}[Required(ErrorMessage="El nombre es requerido.")][StringLength(80,ErrorMessage="El nombre no puede superar 80 caracteres.")]public string Name{get;set;}="";[Required(ErrorMessage="El precio es requerido.")][Range(typeof(decimal),"0","79228162514264337593543950335",ErrorMessage="El precio debe ser mayor o igual que cero.")]public decimal Price{get;set;}public bool IsActive{get;set;}}public async Task<IActionResult> OnGetAsync(Guid id,CancellationToken ct){var x=await additions.GetByIdAsync(id,ct);if(x is null)return NotFound();Input=new(){Id=x.Id,ProductId=x.ProductId,Name=x.Name,Price=x.Price,IsActive=x.IsActive};Product=await products.GetByIdAsync(x.ProductId,ct);return Page();}public async Task<IActionResult> OnPostAsync(CancellationToken ct){Product=await products.GetByIdAsync(Input.ProductId,ct);if(!ModelState.IsValid)return Page();if(await additions.ExistsWithNameAsync(Input.ProductId,Input.Name,Input.Id,ct)){ModelState.AddModelError("Input.Name","Ya existe una adición con ese nombre para este producto");return Page();}await additions.UpdateAsync(new Addition{Id=Input.Id,ProductId=Input.ProductId,Name=Input.Name,Price=Input.Price,IsActive=Input.IsActive},ct);TempData["Message"]="Adición guardada correctamente.";return RedirectToPage("/Catalog/Products/Details",new{id=Input.ProductId});}}
